"""Single source of truth for model feature / target column names.

Two tables exist:
  * the REAL table  (data/processed/train_real.parquet): CPCB measurements + Sentinel-2 reflectance
  * the SYNTHETIC demo table (data/processed/train.parquet): generated by scripts/generate_synthetic_train.py
"""

# Spectral features available for every real visit (water temperature has no in-situ or satellite source here).
REAL_FEATURE_COLS = ["B2", "B3", "B4", "B5", "B6", "B8", "B11", "ndci", "bdm2", "bdm3", "red_green", "nir"]
REAL_TARGET_COLS = ["do", "bod", "turbidity"]          # real labels; Chl-a has no ground truth

# Synthetic demo table (includes a simulated surface temperature and a simulated Chl-a label).
SYNTH_FEATURE_COLS = ["B2", "B3", "B4", "B5", "B8", "B11", "ndci", "bdm2", "bdm3", "red_green", "nir",
                      "temp_surface"]
SYNTH_TARGET_COLS = ["chl_a", "turbidity", "do"]

# Targets whose distribution is heavy-tailed: modelled on a log1p scale.
LOG_TARGETS = ("bod", "turbidity", "chl_a")

META_COLS = ["site", "water_body_type", "lat", "lon", "date", "sensor"]
